-- Regional pack Kalimdor, Thunder Bluff (content wave W01: the city on the mesas, its rises and its bridges). Written through the authoring archive
-- (tools/archive, CONTRIBUTING.md); the texts are in AzerothUnspoken_Kalimdor_enUS/ThunderBluff.lua and AzerothUnspoken_Kalimdor_itIT/ThunderBluff.lua. Built while
-- the character is in the area "mulgore" and dropped when it leaves it (ADR 0048); the folder is loaded with the region
-- (ADR 0025). Races, classes, weather, the time of day and the moment are conditions inside the rules, never separate
-- packs. Subzone names are those of the English Classic client and are not yet confirmed in Forever (#36): a wrong
-- name only keeps a line silent.
